from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class Geometry:
    points: tuple[int, ...]
    lines: tuple[int, ...]
    incident: Callable[[int, int], bool]

def parallel(g: Geometry, a: int, b: int) -> bool:
    return not any(g.incident(p, a) and g.incident(p, b) for p in g.points)

def playfair(g: Geometry) -> bool:
    for p in g.points:
        for line in g.lines:
            if not g.incident(p, line):
                candidates = [m for m in g.lines if g.incident(p, m) and parallel(g, m, line)]
                if len(candidates) != 1:
                    return False
    return True

if __name__ == "__main__":
    universe = (0, 1, 2)
    affine = Geometry(universe, universe, lambda p, line: p == line)
    intersecting = Geometry(universe, universe, lambda p, line: p == 0 or p == line)
    print("Affine witness:", playfair(affine))
    print("Intersecting witness:", playfair(intersecting))

def tropical_factorizations(n: int) -> list[tuple[int, int]]:
    if n < 0:
        raise ValueError("n must be a natural number")
    return [(a, n-a) for a in range(1, n) if n-a > 0]

def tropical_irreducible(n: int) -> bool:
    return n != 0 and not tropical_factorizations(n)

if __name__ == "__main__":
    for n in range(11):
        print(n, tropical_irreducible(n), tropical_factorizations(n))

from typing import Iterable

def universal_core(base: set[str], extensions: Iterable[set[str]]) -> set[str]:
    data = list(extensions)
    if not data or any(not base <= extension for extension in data):
        raise ValueError("provide extensions containing the base")
    core = set(data[0])
    for extension in data[1:]:
        core &= extension
    return core

if __name__ == "__main__":
    base = {"A", "B"}
    extensions = [base, {"A", "B", "C"}, {"A", "B", "D"}]
    print(universal_core(base, extensions))

