from math import isqrt
from typing import Callable

def first_prime_image(bound: int, encode: Callable[[int], str]) -> tuple[int, str]:
    candidate = max(2, bound + 1)
    while True:
        if all(candidate % d != 0 for d in range(2, isqrt(candidate) + 1)):
            return candidate, encode(candidate)
        candidate += 1

